'use client';

import React, { useState } from 'react';
import Header from '../components/Header';
import Hero from '../components/Hero';
import Problem from '../components/Problem';
import Solution from '../components/Solution';
import Arbitrage from '../components/Arbitrage';
import Process from '../components/Process';
import LeadCaptureForm from '../components/LeadCaptureForm';
import Footer from '../components/Footer';
import { translations } from '../locales/translations';

export default function Home() {
  const [lang, setLang] = useState<'fr' | 'en'>('fr');
  const t = translations[lang];

  const handleCtaClick = () => {
    const target = document.getElementById('estimate-form');
    if (target) {
      target.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-brand-bg-primary text-brand-text-primary overflow-x-hidden selection:bg-brand-accent-primary/35 selection:text-brand-accent-light">
      {/* Premium floating navigation header */}
      <Header t={t} lang={lang} setLang={setLang} onCtaClick={handleCtaClick} />

      {/* Main content grid */}
      <main className="flex-1">
        {/* Section 1: Hero */}
        <Hero t={t} onCtaClick={handleCtaClick} />

        {/* Section 2: Problem Bento */}
        <Problem t={t} />

        {/* Section 3: Molecular Solution */}
        <Solution t={t} />

        {/* Section 4: Financial Arbitrage matrix */}
        <Arbitrage t={t} onCtaClick={handleCtaClick} />

        {/* Section 5: The 3-Step Process */}
        <Process t={t} />

        {/* Section 6: Interactive Lead Capture Form */}
        <LeadCaptureForm t={t} />
      </main>

      {/* Footer */}
      <Footer t={t} />
    </div>
  );
}
