'use client';

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Calendar, User, MapPin, Phone, Envelope, ArrowRight, ArrowLeft, CheckCircle, ShieldCheck } from '@phosphor-icons/react';
import { TranslationKeys } from '../locales/translations';

interface LeadCaptureFormProps {
  t: TranslationKeys;
}

export default function LeadCaptureForm({ t }: LeadCaptureFormProps) {
  const [step, setStep] = useState<1 | 2 | 3>(1);
  const [formData, setFormData] = useState({
    roofAge: '',
    fullName: '',
    city: '',
    phone: '',
    email: '',
  });
  
  const [formErrors, setFormErrors] = useState<Record<string, string>>({});
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleAgeSelect = (age: string) => {
    setFormData(prev => ({ ...prev, roofAge: age }));
    setFormErrors(prev => ({ ...prev, roofAge: '' }));
    // Auto-advance after selection for super slick UX
    setTimeout(() => {
      setStep(2);
    }, 300);
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
    setFormErrors(prev => ({ ...prev, [name]: '' }));
  };

  const validateStep2 = () => {
    const errors: Record<string, string> = {};
    if (!formData.fullName.trim()) errors.fullName = 'Le nom est requis / Name is required';
    if (!formData.city.trim()) errors.city = 'La ville est requise / City is required';
    if (!formData.phone.trim()) {
      errors.phone = 'Le téléphone est requis / Phone is required';
    } else if (!/^\+?[\d\s-()]{7,15}$/.test(formData.phone.trim())) {
      errors.phone = 'Format invalide / Invalid phone format';
    }
    if (!formData.email.trim()) {
      errors.email = 'Le courriel est requis / Email is required';
    } else if (!/\S+@\S+\.\S+/.test(formData.email.trim())) {
      errors.email = 'Format invalide / Invalid email format';
    }

    setFormErrors(errors);
    return Object.keys(errors).length === 0;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!validateStep2()) return;

    setIsSubmitting(true);
    
    // Simulate API call to capture lead
    setTimeout(() => {
      setIsSubmitting(false);
      setStep(3);
    }, 1500);
  };

  const handleReset = () => {
    setFormData({
      roofAge: '',
      fullName: '',
      city: '',
      phone: '',
      email: '',
    });
    setStep(1);
  };

  return (
    <section id="estimate-form" className="relative py-24 md:py-32 px-6 md:px-12 bg-brand-bg-primary overflow-hidden border-t border-brand-border-light">
      <div className="absolute top-[50%] right-[-10%] w-[45vw] h-[45vw] bg-brand-accent-primary/5 rounded-full filter blur-[120px] pointer-events-none" />
      <div className="absolute bottom-[10%] left-[-10%] w-[35vw] h-[35vw] bg-brand-accent-primary/5 rounded-full filter blur-[100px] pointer-events-none" />

      <div className="max-w-4xl w-full mx-auto relative z-10">
        
        {/* Header Block */}
        <div className="max-w-3xl mb-12 text-left">
          <h2 className="font-extrabold text-3xl sm:text-4xl lg:text-5xl tracking-tight text-brand-text-primary leading-[1.1] mb-4">
            {t.formTitle}
          </h2>
          <p className="text-brand-text-secondary text-base sm:text-lg">
            {t.formSubtitle}
          </p>
        </div>

        {/* Form Progress Indicator (Only visible in steps 1 and 2) */}
        {step < 3 && (
          <div className="flex items-center gap-4 mb-8">
            <span className="text-xs font-bold uppercase tracking-wider text-brand-accent-light">
              {t.formStepCount.replace('{current}', String(step)).replace('{total}', '2')}
            </span>
            <div className="flex-1 h-1.5 rounded-full bg-brand-bg-secondary border border-brand-border-light overflow-hidden">
              <div 
                className="h-full bg-brand-accent-primary transition-all duration-500 ease-out"
                style={{ width: `${step === 1 ? 50 : 100}%` }}
              />
            </div>
          </div>
        )}

        {/* Glassmorphic Form Card Wrapper */}
        <div className="w-full rounded-3xl glass-card p-8 lg:p-12 shadow-2xl relative overflow-hidden">
          
          <AnimatePresence mode="wait">
            
            {/* STEP 1: Roof Age Radio Options */}
            {step === 1 && (
              <motion.div
                key="step1"
                initial={{ opacity: 0, x: -20 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: 20 }}
                transition={{ duration: 0.3 }}
                className="flex flex-col gap-6"
              >
                <h3 className="font-bold text-lg lg:text-xl text-brand-text-primary flex items-center gap-2 mb-2">
                  <Calendar className="h-5 w-5 text-brand-accent-primary" weight="fill" />
                  {t.formAgeQuestion}
                </h3>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  {[
                    { label: t.formAge1, val: '1-5' },
                    { label: t.formAge2, val: '6-10' },
                    { label: t.formAge3, val: '11-15' },
                    { label: t.formAge4, val: '15+' },
                  ].map((opt) => (
                    <button
                      key={opt.val}
                      type="button"
                      onClick={() => handleAgeSelect(opt.val)}
                      className={`p-6 rounded-2xl border text-left font-bold text-sm sm:text-base flex items-center justify-between transition-all duration-200 cursor-pointer ${
                        formData.roofAge === opt.val
                          ? 'border-brand-accent-primary bg-brand-accent-primary/10 text-brand-accent-light shadow-lg'
                          : 'border-brand-border-light bg-brand-bg-secondary/40 text-brand-text-secondary hover:border-brand-accent-primary/30 hover:bg-brand-bg-secondary/60 hover:text-brand-text-primary'
                      }`}
                    >
                      <span>{opt.label}</span>
                      <div className={`h-5 w-5 rounded-full border flex items-center justify-center transition-all duration-200 ${
                        formData.roofAge === opt.val
                          ? 'border-brand-accent-primary bg-brand-accent-primary text-brand-text-primary'
                          : 'border-brand-text-muted bg-transparent'
                      }`}>
                        {formData.roofAge === opt.val && <div className="h-2 w-2 rounded-full bg-brand-text-primary" />}
                      </div>
                    </button>
                  ))}
                </div>
                {formErrors.roofAge && (
                  <p className="text-red-500 text-xs font-semibold">{formErrors.roofAge}</p>
                )}
              </motion.div>
            )}

            {/* STEP 2: Main Contact Fields */}
            {step === 2 && (
              <motion.div
                key="step2"
                initial={{ opacity: 0, x: -20 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: 20 }}
                transition={{ duration: 0.3 }}
              >
                <form onSubmit={handleSubmit} className="flex flex-col gap-6">
                  <h3 className="font-bold text-lg lg:text-xl text-brand-text-primary flex items-center gap-2 mb-2">
                    <ShieldCheck className="h-5 w-5 text-brand-accent-primary" weight="fill" />
                    {t.formInfoTitle}
                  </h3>

                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                    {/* Full Name */}
                    <div className="flex flex-col gap-2">
                      <label className="text-xs font-bold uppercase tracking-wider text-brand-text-secondary flex items-center gap-1.5">
                        <User className="h-3.5 w-3.5 text-brand-accent-primary" weight="bold" />
                        {t.formLabelName}
                      </label>
                      <input
                        type="text"
                        name="fullName"
                        value={formData.fullName}
                        onChange={handleInputChange}
                        placeholder="Lend Dedinca"
                        className={`w-full px-4 py-3.5 rounded-xl border bg-brand-bg-secondary/50 text-brand-text-primary text-sm focus:outline-none transition-all duration-200 ${
                          formErrors.fullName 
                            ? 'border-red-500/50 focus:border-red-500' 
                            : 'border-brand-border-light focus:border-brand-accent-primary/60 focus:ring-1 focus:ring-brand-accent-primary/20'
                        }`}
                      />
                      {formErrors.fullName && <p className="text-red-500 text-[11px] font-semibold">{formErrors.fullName}</p>}
                    </div>

                    {/* City */}
                    <div className="flex flex-col gap-2">
                      <label className="text-xs font-bold uppercase tracking-wider text-brand-text-secondary flex items-center gap-1.5">
                        <MapPin className="h-3.5 w-3.5 text-brand-accent-primary" weight="bold" />
                        {t.formLabelCity}
                      </label>
                      <input
                        type="text"
                        name="city"
                        value={formData.city}
                        onChange={handleInputChange}
                        placeholder="Montréal / Longueuil / Laval"
                        className={`w-full px-4 py-3.5 rounded-xl border bg-brand-bg-secondary/50 text-brand-text-primary text-sm focus:outline-none transition-all duration-200 ${
                          formErrors.city 
                            ? 'border-red-500/50 focus:border-red-500' 
                            : 'border-brand-border-light focus:border-brand-accent-primary/60 focus:ring-1 focus:ring-brand-accent-primary/20'
                        }`}
                      />
                      {formErrors.city && <p className="text-red-500 text-[11px] font-semibold">{formErrors.city}</p>}
                    </div>

                    {/* Phone Number */}
                    <div className="flex flex-col gap-2">
                      <label className="text-xs font-bold uppercase tracking-wider text-brand-text-secondary flex items-center gap-1.5">
                        <Phone className="h-3.5 w-3.5 text-brand-accent-primary" weight="bold" />
                        {t.formLabelPhone}
                      </label>
                      <input
                        type="tel"
                        name="phone"
                        value={formData.phone}
                        onChange={handleInputChange}
                        placeholder="514-555-0199"
                        className={`w-full px-4 py-3.5 rounded-xl border bg-brand-bg-secondary/50 text-brand-text-primary text-sm focus:outline-none transition-all duration-200 ${
                          formErrors.phone 
                            ? 'border-red-500/50 focus:border-red-500' 
                            : 'border-brand-border-light focus:border-brand-accent-primary/60 focus:ring-1 focus:ring-brand-accent-primary/20'
                        }`}
                      />
                      {formErrors.phone && <p className="text-red-500 text-[11px] font-semibold">{formErrors.phone}</p>}
                    </div>

                    {/* Email */}
                    <div className="flex flex-col gap-2">
                      <label className="text-xs font-bold uppercase tracking-wider text-brand-text-secondary flex items-center gap-1.5">
                        <Envelope className="h-3.5 w-3.5 text-brand-accent-primary" weight="bold" />
                        {t.formLabelEmail}
                      </label>
                      <input
                        type="email"
                        name="email"
                        value={formData.email}
                        onChange={handleInputChange}
                        placeholder="lend@solutionseal.ca"
                        className={`w-full px-4 py-3.5 rounded-xl border bg-brand-bg-secondary/50 text-brand-text-primary text-sm focus:outline-none transition-all duration-200 ${
                          formErrors.email 
                            ? 'border-red-500/50 focus:border-red-500' 
                            : 'border-brand-border-light focus:border-brand-accent-primary/60 focus:ring-1 focus:ring-brand-accent-primary/20'
                        }`}
                      />
                      {formErrors.email && <p className="text-red-500 text-[11px] font-semibold">{formErrors.email}</p>}
                    </div>
                  </div>

                  {/* Actions buttons */}
                  <div className="flex flex-col sm:flex-row items-center justify-between gap-4 mt-6 pt-6 border-t border-brand-border-light">
                    <button
                      type="button"
                      onClick={() => setStep(1)}
                      className="inline-flex items-center justify-center gap-2 px-6 py-3.5 text-xs font-bold uppercase tracking-wider rounded-xl border border-brand-border-light hover:border-brand-accent-primary/20 hover:bg-brand-bg-secondary text-brand-text-secondary hover:text-brand-text-primary active:scale-95 transition-all duration-200 cursor-pointer w-full sm:w-auto"
                    >
                      <ArrowLeft className="h-3.5 w-3.5" weight="bold" />
                      {t.formBtnBack}
                    </button>
                    
                    <button
                      type="submit"
                      disabled={isSubmitting}
                      className="inline-flex items-center justify-center gap-2 px-8 py-3.5 text-xs font-bold uppercase tracking-wider rounded-xl bg-brand-accent-primary hover:bg-brand-accent-hover text-brand-text-primary shadow-lg shadow-brand-accent-primary/20 active:scale-95 disabled:opacity-50 transition-all duration-200 cursor-pointer w-full sm:w-auto"
                    >
                      <span>{isSubmitting ? 'Calcul...' : t.formBtnSubmit}</span>
                      {!isSubmitting && <ArrowRight className="h-3.5 w-3.5" weight="bold" />}
                    </button>
                  </div>
                </form>
              </motion.div>
            )}

            {/* STEP 3: Beautiful Success Screen */}
            {step === 3 && (
              <motion.div
                key="step3"
                initial={{ opacity: 0, scale: 0.95 }}
                animate={{ opacity: 1, scale: 1 }}
                exit={{ opacity: 0, scale: 0.95 }}
                transition={{ duration: 0.4, ease: [0.16, 1, 0.3, 1] as any }}
                className="flex flex-col items-center text-center py-8"
              >
                <div className="h-16 w-16 rounded-full bg-brand-accent-primary/10 border border-brand-accent-primary/30 flex items-center justify-center text-brand-accent-primary mb-6 shadow-xl shadow-brand-accent-primary/10 animate-bounce">
                  <CheckCircle className="h-10 w-10" weight="fill" />
                </div>
                
                <h3 className="font-extrabold text-2xl lg:text-3xl text-brand-accent-light mb-3">
                  {t.formSuccessTitle}
                </h3>
                <p className="font-bold text-sm text-brand-text-primary mb-6">
                  {t.formSuccessSubtitle}
                </p>
                <p className="text-brand-text-secondary text-sm lg:text-base leading-relaxed max-w-lg mb-8">
                  {t.formSuccessMessage}
                </p>

                <button
                  type="button"
                  onClick={handleReset}
                  className="inline-flex items-center justify-center px-8 py-3.5 text-xs font-bold uppercase tracking-wider rounded-xl bg-brand-bg-secondary border border-brand-border-light hover:border-brand-accent-primary/20 hover:text-brand-accent-light text-brand-text-secondary active:scale-95 transition-all duration-200 cursor-pointer"
                >
                  {t.formSuccessBtn}
                </button>
              </motion.div>
            )}
          </AnimatePresence>
          
        </div>

        {/* GDPR disclaimer bar */}
        {step < 3 && (
          <div className="w-full text-center mt-6 text-xs text-brand-text-muted tracking-wide">
            {t.formGdpr}
          </div>
        )}
      </div>
    </section>
  );
}
